// План specs/admin-coupons.md 1.1–1.3 (кейсы .qa/tests/admin-coupons/CP-01…CP-03). Admin, десктоп, EN.
// @prod-safe: только чтение формы — Save НЕ нажимается, купоны не создаются и не меняются (страховка blockCouponWrites).
// Сохранение купона с пустым лимитом / лимитом 1 — ручной кейс CP-04 (купоны не удаляются, живой Stripe).
import { test, expect } from '../../fixtures';
import {
  LIMIT3_COUPON, UNLIMITED_COUPON,
  blockCouponWrites, cancelDialog, couponDialog, couponRow, expectEmptyLimitAccepted, expectLimitRejected,
  expectNoCouponWrites, openCoupons, openNewCouponFilled, restoreTest, saveButton, startInTest,
} from './coupon-helpers';

// Источник: «מה רצוי» — מגבלה 0 לא נשמרת, מוצגת הודעת שגיאה ו-Save לא שומר; комментарий программиста — 0 или нецелое число.
const BAD_LIMITS = ['0', '-1', '1.5'];

test.describe('Admin coupons: redemption limit (#351eb3)', () => {
  test('New coupon: limit 0 / negative / fractional shows "At least 1…" error and Save is disabled; empty limit is accepted (not saved) #351eb3 @desktop @prod-safe', async ({ asUser }) => {
    const page = await asUser('admin');
    await startInTest(page);
    const writes = await blockCouponWrites(page);
    try {
      await openCoupons(page);
      const dlg = await openNewCouponFilled(page);
      for (const v of BAD_LIMITS) await expectLimitRejected(dlg, v);
      await expectEmptyLimitAccepted(dlg);
      await cancelDialog(page);
    } finally {
      await restoreTest(page);
    }
    expectNoCouponWrites(writes);
  });

  test('Edit coupon: limit 0 / negative / fractional shows "At least 1…" error and Save is disabled (Cancel, nothing saved) #351eb3 @desktop @prod-safe', async ({ asUser }) => {
    const page = await asUser('admin');
    await startInTest(page);
    const writes = await blockCouponWrites(page);
    try {
      await openCoupons(page);
      // Edit есть только у активных купонов; берём активный QA-купон, иначе любой активный (только открываем форму, Cancel).
      const editable = page.locator('tr, [role="row"]').filter({ has: page.getByRole('button', { name: 'Edit', exact: true }) });
      const qaEditable = editable.filter({ hasText: /QA-/ });
      const row = (await qaEditable.count()) > 0 ? qaEditable.first() : editable.first();
      test.skip((await editable.count()) === 0, 'нет активного купона с кнопкой Edit — проверить Edit вручную (CP-02)');

      await row.getByRole('button', { name: 'Edit', exact: true }).click();
      const dlg = couponDialog(page);
      await expect(dlg.getByRole('heading', { name: 'Edit coupon' })).toBeVisible();
      for (const v of BAD_LIMITS) await expectLimitRejected(dlg, v);
      await expect(saveButton(dlg)).toBeDisabled();
      await cancelDialog(page);
    } finally {
      await restoreTest(page);
    }
    expectNoCouponWrites(writes);
  });

  test('Coupons list: coupon without limit shows "0 / ∞" in Used, limited one "N / limit" #351eb3 @desktop @prod-safe', async ({ asUser }) => {
    const page = await asUser('admin');
    await startInTest(page);
    const writes = await blockCouponWrites(page);
    try {
      await openCoupons(page);
      // Источник: «מה רצוי» — ברשימה ברור מתי קופון בלי מגבלה (למשל "0 / ∞").
      await expect(couponRow(page, UNLIMITED_COUPON)).toContainText(/\b0\s*\/\s*∞/);
      await expect(couponRow(page, LIMIT3_COUPON)).toContainText(/\b0\s*\/\s*3\b/);
      // Ни в одной строке Used не показано «голое» число без «/ лимит».
      const usedCells = await page.locator('tbody tr').evaluateAll((rows) => {
        const ths = Array.from(document.querySelectorAll('thead th')).map((t) => (t.textContent ?? '').trim());
        const idx = ths.indexOf('Used');
        return rows.map((r) => (r.querySelectorAll('td')[idx]?.textContent ?? '').trim());
      });
      expect(usedCells.length, 'в списке есть купоны').toBeGreaterThan(0);
      for (const cell of usedCells) expect(cell, 'Used = «N / лимит» или «N / ∞»').toMatch(/^\d+\s*\/\s*(\d+|∞)$/);
      await expect(couponDialog(page)).toBeHidden();
    } finally {
      await restoreTest(page);
    }
    expectNoCouponWrites(writes);
  });
});
